// One learner goal (canDo) and 4+ specific sub-goals per B1 lesson, shared by all three sheets
// (docs/LESSON_QUALITY_CONTRACT.md A1–A3, owner 2026-10-12). Lessons 1–50 come from their reviewed Avasta sheets,
// 51–75 were rewritten from the generic course defaults. Block goal ids (g_vocab, g_read, g_notice, g_use) stay.
export const B1_LESSON_GOALS = {
  "a2b1-001": {"canDo":"Ma teen sisenemistesti neli osa ja saan teada, millised oskused ja vormid vajavad harjutamist.","goals":{"g_vocab":"Õpilane tunneb ära igapäevaelu, töö ja vaba aja sõnad siltidel, kuulutustes ja lühisõnumites.","g_read":"Õpilane lahendab lugemise ja kuulamise ülesanded ajapiiranguga ja näeb oma tulemust osade kaupa.","g_notice":"Õpilane näitab, kuidas ta kasutab kohakäändeid, lihtminevikku, osastavat sihitist, ma- ja da-infinitiivi ning tingivat kõneviisi.","g_use":"Õpilane kirjutab õpetajale sõnumi ja lühikese loo, räägib endast ja helistab keelekooli; õpetaja hindab rubriigiga."}},
  "a2b1-002": {"canDo":"Ma kirjutan sõbrale 70–90-sõnalise kirja sellest, mis eile juhtus, ja oma plaanist homseks.","goals":{"g_vocab":"Õpilane kasutab päeva sündmuste sõnu: magama jääma, hiljaks jääma, maha jääma, kiirustama, unustama, õnneks, kahjuks.","g_read":"Õpilane mõistab Anna päevikust, Markuse loost ja Liisi häälsõnumist, mis juhtus ja mis järjekorras.","g_notice":"Õpilane moodustab lihtmineviku jaatava ja eitava vormi (jäin, ei jõudnud) ja paneb ajasõna järel tegusõna teisele kohale.","g_use":"Õpilane jutustab oma eilsest päevast, lahendab telefonis bussiprobleemi ja kirjutab sõbrannale 70–90-sõnalise kirja."}},
  "a2b1-003": {"canDo":"Ma küsitlen kolleegi tema harjumuste kohta ja lepin rühmaga kokku kolm uut harjumust.","goals":{"g_vocab":"Õpilane kasutab harjumuste sõnu: harjumus, tervislik, magus, trepp, liikuma, loobuma, piisavalt, vähem, rohkem.","g_read":"Õpilane mõistab raadiouuringust, Markuse blogist ja kolleegide kaartidest, kes mida teeb ja kui tihti.","g_notice":"Õpilane kasutab osastavat sihitist (joon kohvi, ei söönud kooki) ja valib ma- või da-infinitiivi (pean jooma, tahan juua).","g_use":"Õpilane küsitleb paarilist, räägib tulemustest ja lepib kokku kontori tervisenädala kolm harjumust."}},
  "a2b1-004": {"canDo":"Ma helistan keelekooli, selgitan oma probleemi ja lepin viisakalt kokku uue tunniaja.","goals":{"g_vocab":"Õpilane kasutab nädalaplaani sõnu: rühm, ujula, jõusaal, vaba, muutma, sobima, ära jääma, asemel, numbrid ja kellaajad.","g_read":"Õpilane mõistab sõnumitest, kuulutustest, spordikeskuse kavast ja keelekooli kirjast, mis muutus, kus ja millal.","g_notice":"Õpilane valib kus-, kuhu- ja kust-vormi (ujulas, ujulasse, ujulast) ja palub tingiva kõneviisiga (Kas te saaksite…?).","g_use":"Õpilane lepib Sofiaga kokku uue nädalaplaani, helistab keelekooli administraatorile ja kirjutab sõbrale kutse."}},
  "a2b1-005": {"canDo":"Ma sooritan mooduli kontrolli Harno A2 vormis ja saan igas osas vähemalt 60% punktidest.","goals":{"g_read":"Õpilane saab lugemise ja kuulamise ülesannetes vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti lihtminevikku, osastavat sihitist, ma- ja da-infinitiivi, kohakäändeid ja tingivat palvet.","g_use":"Õpilane kirjutab sõnumi ja kirja, räägib oma nädalast ja lepib kokku kohtumise; kirjutamises ja rääkimises vähemalt 60%."}},
  "a2b1-006": {"canDo":"Ma kirjutan 60–80-sõnalise loo ühest pildist oma perealbumist: kes on pildil, kes nad mulle on ja mis siis juhtus.","goals":{"g_vocab":"Õpilane kasutab sugulussõnu ja liitsõnu: sugulane, onu, tädi, nõbu, vanavanemad, lapselaps, vennatütar, õepoeg.","g_read":"Õpilane mõistab Sofia lugu vanast fotost, Helgi meenutust ja Maie häälsõnumit: kes on kes ja mis juhtus.","g_notice":"Õpilane moodustab omastava küsimusele kelle? (Viktori, õe, venna, sugulaste) ja kirjeldab sugulust: minu ema vend = onu.","g_use":"Õpilane tutvustab end peol kaugele sugulasele ja kirjutab 60–80-sõnalise loo pildist oma perealbumist."}},
  "a2b1-007": {"canDo":"Ma räägin kes-lausetega, milline inimene sobib lastele hoidjaks, ja lepin paarilisega kokku ühe kandidaadi.","goals":{"g_vocab":"Õpilane kasutab välimuse ja iseloomu sõnu: habe, prillid, lokkis, rahulik, täpne, kannatlik, tagasihoidlik, abivalmis.","g_read":"Õpilane saab aru Sofia kolleegide häälsõnumitest, kaubanduskeskuse teadaandest, raadiointervjuust ja Kadri kuulutusest.","g_notice":"Õpilane ühendab laused kes-kõrvallausega (kes, kelle, keda, kellel, kellega …) ja paneb kõrvallause ümber komad.","g_use":"Õpilane seletab teisele raadios kuuldut, kirjeldab kandidaate kes-lausetega ja lepib paarilisega kokku ühe hoidja."}},
  "a2b1-008": {"canDo":"Ma helistan leitud asjade büroosse, kirjeldan oma kaotatud asja mis-lausetega ja küsin, kuidas selle tagasi saan.","goals":{"g_vocab":"Õpilane kasutab kaotamise ja leidmise sõnu: kaotama, leidma, unustama, kaduma, omanik, leitud asjad, büroo, tasu.","g_read":"Õpilane mõistab pargi kohviku teadet, rongi teadaannet, raadiolugu leitud asjade büroost ja Viktori sõnumit.","g_notice":"Õpilane eristab oma ja tema (Oskar võttis oma jope) ning kirjeldab asja mis-lausega: kott, mille ma kaotasin; vihmavari, mida ta otsib.","g_use":"Õpilane kirjeldab telefonis oma kaotatud asja, küsib vajaliku info ning kirjutab sõbrale ja ametlikult eri moodi."}},
  "a2b1-009": {"canDo":"Ma kirjutan sugulastele 80–100-sõnalise kirja Helgi üllatuspeost: kus ja millal, mida kaasa võtta ja miks see on saladus.","goals":{"g_vocab":"Õpilane kasutab peo ja kokkuleppe sõnu: ettepanek, eelistama, kokku leppima, kokkulepe, kingitus, üllatus, saladus, põhjus.","g_read":"Õpilane mõistab Jaani häälsõnumist, kuulutustest, Liisi blogist ja peo plaanist numbrid, pakkumised ja selle, mis on veel lahtine.","g_notice":"Õpilane teeb ettepaneku (Lähme…!, Võiksime…), põhjendab sest- või kuna-lausega ja sõnastab kokkuleppe: Lepime kokku, et…","g_use":"Õpilane tellib telefonis peotoidu, lepib pere nõupidamisel kokku peo plaani ja kirjutab sugulastele 80–100-sõnalise kutsekirja."}},
  "a2b1-010": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: loen, kuulan, kirjutan ja räägin pere ja suhete teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80% punktidest.","g_notice":"Õpilane kasutab õigesti omastavat, oma/tema, ta on / tal on ning kes- ja mis-lauseid.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 80% punktidest."}},
  "a2b1-011": {"canDo":"Ma kirjutan emale 80–100-sõnalise kirja korterist, mille leidsin: milline see on, mis on hea ja halb ning millised on üüritingimused.","goals":{"g_vocab":"Õpilane kasutab kodu ja üürimise sõnu: üürima, üürnik, üür, leping, omanik, korrus, niiske, ruumikas, ebameeldiv, ohutu.","g_read":"Õpilane saab aru korterite häälsõnumitest, korteri vaatamisest, raadiosaatest üürimise kohta, maja teadetest ja omaniku sõnumist: milline korter on ja mis on tingimused.","g_notice":"Õpilane moodustab ja mõistab liitega omadussõnu: -ne/-line (kivine, päikeseline), -kas (ruumikas), -lik (rahulik), -tu (ohutu), eba- (ebamugav).","g_use":"Õpilane kirjeldab korterit, seletab Jaanile omaniku tingimusi, küsib omanikult telefonis üle ja kirjutab emale 80–100-sõnalise kirja."}},
  "a2b1-012": {"canDo":"Ma kirjutan 80–100-sõnalise loo oma kolimispäevast: kust ja kuhu kolisin, kes aitas ja kuhu asjad panin.","goals":{"g_vocab":"Õpilane kasutab kolimise sõnu: kolima, pakkima, kast, kandma, trepikoda, kelder, aknalaud, reegel, kapp, sahver.","g_read":"Õpilane loeb Sofia blogi, Malle kirja, maja reegleid ja Helgi kirja ning leiab, mis kus on ja kuhu mida viia.","g_notice":"Õpilane valib kus-, kuhu- ja kust-vormi (kastis – kasti – kastist, riiulil – riiulile – riiulilt, Malle juures – juurde – juurest) ja lühikese kuhu-vormi: tuppa, kööki, koju.","g_use":"Õpilane kirjutab naabritele viisaka teate, lepib kokku, kuhu mööbel läheb, ning kirjutab loo oma kolimispäevast ja sõpradele kutse."}},
  "a2b1-013": {"canDo":"Ma räägin oma linnaosast, põhjendan arvamust ja lepin seltsi koosolekul kokku ühe ettepaneku.","goals":{"g_vocab":"Õpilane kasutab linnaosa ja linnakohtade sõnu: linnaosa, elanik, selts, krunt, mänguväljak, turg, raamatukogu, koosolek, rahustav, talgud.","g_read":"Õpilane saab aru elanike arvamustest raadios, Tiina ringkäigust ja intervjuust, kolme linnaosa tutvustusest ja elanike ettepanekutest.","g_notice":"Õpilane kirjeldab kohta liitega omadussõnadega (rahulik, lärmakas, ohutu, roheline, kodune, ebamugav) ja põhjendab arvamust sest- ja kuna-lausega.","g_use":"Õpilane küsitleb inimesi nende kodukoha kohta, ütleb oma arvamuse, lepib koosolekul kokku ühe ettepaneku ja kirjutab seltsile kokkuvõtte."}},
  "a2b1-014": {"canDo":"Ma räägin hooldusfirma töötajaga, kirjeldan riket ja lepin kokku, millal ja kuidas see parandatakse.","goals":{"g_vocab":"Õpilane kasutab rikke ja teejuhatuse sõnu: rike, katki, radiaator, remont, suletud, ristmik, otse, pöörama, eksima, ümbersõit.","g_read":"Õpilane loeb kuulutusi, Viktori sõnumit, hooldusfirma tingimusi ja päevakava ning leiab, mis on muutunud ja kes saab aidata.","g_notice":"Õpilane juhatab teed sõbrale ja võõrale (mine – minge, pööra – pöörake, ära mine – ärge minge) ja kasutab -ni vormi: kuni ristmikuni, pargini.","g_use":"Õpilane otsustab, mida esimesena teha, juhatab telefonis teed, lahendab rikke hooldusfirmaga ja kirjutab külalistele selge teekirjelduse."}},
  "a2b1-015": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis: loen, kuulan, kirjutan ja räägin kodu ja linna teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80% punktidest.","g_notice":"Õpilane kasutab õigesti liitega omadussõnu, kus-, kuhu- ja kust-vorme ning käsku sõbrale ja võõrale.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 80% punktidest.","g_vocab":"Õpilane kasutab mooduli 3 kodu, kolimise, linnaosa ja tee sõnu ilma toeta."}},
  "a2b1-016": {"canDo":"Ma räägin laagri päevakavast vähemalt kuue ajamäärusega ja lepin paarilisega kokku laupäeva kava.","goals":{"g_vocab":"Õpilane kasutab aja ja kava sõnu: kava, päevakava, kestma, veerand, kolmveerand, hiljemalt, vähemalt, öörahu, kui tihti.","g_read":"Õpilane leiab Kaie kirjast, häälsõnumist, Oskari päevikust ja vabatahtlike kaartidelt, mis toimub millal ja kui kaua.","g_notice":"Õpilane ütleb kellaaja (veerand, pool, kolmveerand), kestuse (kella üheksast kella kümneni) ning kasutab enne / pärast + osastavat ja kuni …-ni.","g_use":"Õpilane räägib oma päevast, küsib lahtiolekuaegu, lepib paarilisega kokku laagri päevakava ja vastab mures lapsevanemale."}},
  "a2b1-017": {"canDo":"Ma saan kuuldust aru, mida tööl peab, võib ja ei tohi teha, ja kirjutan sõbrale 80–100-sõnalise kirja tema uue töö reeglitest.","goals":{"g_vocab":"Õpilane kasutab reeglite sõnu: reegel, kohustus, luba, keelatud, lubatud, kandma, turvavest, ladu, lisatöötaja, ajutine.","g_read":"Õpilane saab aru lühiteadetest, Liisi juhendist, raadiointervjuust ja lasteaia häälsõnumist: mis on kohustus, luba või keeld.","g_notice":"Õpilane kasutab peab / ei pea + ma-vormi ning võib, tohib, saab, ei tohi, on vaja + da-vormi ja eristab ei pea ja ei tohi.","g_use":"Õpilane kirjutab kolleegile lühiteate (Harno B1 kirjutamine 1), seletab sõbrale kuuldud reegleid ja kirjutab talle kirja."}},
  "a2b1-018": {"canDo":"Ma loen kolleegi juhendist, mis tuleb ära teha ja mis võib oodata, ja kirjutan 80–100-sõnalise loo kahest päevast kolleegi asemel.","goals":{"g_vocab":"Õpilane kasutab ühendverbe ja töö sõnu: läbi lugema, ette valmistama, ära maksma, edasi lükkama, ära jääma, tähtaeg, aruanne, nimekiri.","g_read":"Õpilane mõistab Markuse lugu, ajakirja nõuandeid ja Anna kirja: mis on kiire, mis võib oodata ja mida pole vaja teha.","g_notice":"Õpilane paneb ühendverbi osakese õigesse kohta: Ma loen lepingu läbi; Ma ei loe lepingut läbi; Ma pean lepingu läbi lugema.","g_use":"Õpilane jutustab Markuse päevast, vastab ülemuse küsimustele tehtud tööde kohta ja kirjutab loo kahest päevast kolleegi asemel."}},
  "a2b1-019": {"canDo":"Ma helistan kliinikusse või bussifirmasse, lükkan aja edasi ja lepin kokku uue aja ning perega uue nädalavahetuse plaani.","goals":{"g_vocab":"Õpilane kasutab kokkuleppe sõnu: kokku leppima, kokkulepe, ümber tegema, sobima, kinnitama, kahjuks, ettepanek, keelduma.","g_read":"Õpilane mõistab häälsõnumitest, kuulutustest, siltidest ja artiklist, mis aeg muutus ja kuidas uut aega kokku leppida.","g_notice":"Õpilane teeb viisaka ettepaneku ja keeldub põhjusega (Kas teile sobiks…? Kahjuks ei saa, sest…) ning kasutab ühendverbe edasi lükkama, ära jääma, kokku leppima.","g_use":"Õpilane helistab kliinikusse ja bussifirmasse (Harno B1 rääkimine 2), lepib perega kokku uue plaani ja kirjutab kutse."}},
  "a2b1-020": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis koos ühe B1 ülesandega igas osas ja võrdlen tulemust sisenemistestiga; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest, ka B1 vormis ülesannetes (kuulutused, artikkel, lühiteated, intervjuu).","g_notice":"Õpilane kasutab õigesti moodulite 1–4 vorme: kohakäänded, lihtminevik, osastav, ma/da ja peab/võib, tingiv palve, omastav, ajamäärused, ühendverbid.","g_use":"Õpilane kirjutab teate ja kirja ning räägib endast, oma ajast ja plaanidest ja helistab asutusse; kirjutamises ja rääkimises vähemalt 80 %."}},
  "a2b1-021": {"canDo":"Ma kirjutan haigele kolleegile 80–100-sõnalise kirja sellest, mis tööl juhtus, mida ma tegin ja mida ei teinud.","goals":{"g_vocab":"Õpilane kasutab tööpäeva tegusõnu minevikus: ärkasin, vastasin, kontrollisin, lõpetasin, saatsin, otsisin, muretsesin.","g_read":"Õpilane mõistab Markuse lugu, Anna päevikut, Markuse ja Sofia kõnet ning Liisi kirja: mis juhtus ja mis järjekorras.","g_notice":"Õpilane moodustab -si- ja -s-lihtmineviku kõigis isikutes (vastasin, ta vastas, ostsin) ja eituse: ei vastanud, ei ostnud.","g_use":"Õpilane jutustab loo kaks korda, räägib Liisile kohvipausil ja häälsõnumis nädala uudistest ning kirjutab talle 80–100-sõnalise kirja."}},
  "a2b1-022": {"canDo":"Ma räägin 2 minutit, mida ma eelmisel nädalavahetusel tegin, ja lepin kolleegiga kokku meeskonna laupäevase väljasõidu.","goals":{"g_vocab":"Õpilane kasutab mineviku ajasõnu ja nädalavahetuse tegevusi: üleeile, eelmisel nädalal, … tagasi, kõigepealt, pärast seda, lõpuks, puhkama, koristama.","g_read":"Õpilane mõistab Anna postitust, Viktori raadiokõnet, kolme nädalavahetuse lugu ja kolleegide kaarte: kes mida millal tegi.","g_notice":"Õpilane alustab lauset ajasõnaga ja paneb tegusõna teisele kohale (Laupäeval koristasin ma korteri) ning valib aja järgi mineviku, oleviku või tuleviku.","g_use":"Õpilane küsitleb teisi, räägib 4-3-2 korras oma nädalavahetusest, lepib kokku väljasõidu koha, broneerib selle telefonis ja kirjutab kutse."}},
  "a2b1-023": {"canDo":"Ma räägin festivali korraldajaga: kirjeldan erandlike minevikuvormidega, mis juhtus (tulin, nägin, sain), ja palun probleemile lahendust.","goals":{"g_vocab":"Õpilane kasutab festivali sõnu ja teeb tegusõnast inimese nimetuse: festival, vabatahtlik, järjekord, lava, auhind, müüja, esineja, külastaja.","g_read":"Õpilane saab aru lühikestest raadiouudistest (Harno B1 kuulamine 1), festivali teadetest, Jaani päevikust, korraldaja intervjuust ja häälsõnumist.","g_notice":"Õpilane moodustab -i-lihtmineviku ja sagedased erandid (tuli, sõi, jõi, tõi, viis, sai, läks, tegi, nägi, pani) ning eituse: ei tulnud, ei läinud.","g_use":"Õpilane avaldab arvamust, tutvustab end vabatahtlikuna, kirjeldab korraldajale, mis juhtus, lepib kokku lahenduse, helistab piletiteenindusse ja vastab kirjale."}},
  "a2b1-024": {"canDo":"Ma kirjutan linnalehe võistlusele 80–100-sõnalise loo „Minu kõige ootamatum päev”: algus, probleem, mis edasi juhtus ja lõpp.","goals":{"g_vocab":"Õpilane kasutab loo sõnu: alguses, äkki, märkama, kaduma, mures, õnneks, kahjuks, tagasi saama, ootamatu, pealkiri.","g_read":"Õpilane leiab Anna raadioloost, eelmise aasta võidulugudest ja võistluse reeglitest loo osad, žürii nõuded ja vajaliku info.","g_notice":"Õpilane ühendab laused loo sõnadega (kõigepealt, siis, pärast seda, kui, sest, nii … et) ja paneb ajasõna järel tegusõna teisele kohale.","g_use":"Õpilane kirjutab piltide järgi kiirloo, plaanib ja parandab oma mustandi, täidab ankeedi, kirjutab võistlusele 80–100-sõnalise loo ja otsustab paarilisega nagu žürii."}},
  "a2b1-025": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos esimeste B1 ülesannetega ja saan igas osas vähemalt 80 % punktidest.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest, ka B1 ülesannetes (valiklünktekst, artikkel, lühikesed klipid).","g_notice":"Õpilane kasutab õigesti lihtmineviku -s-, -si- ja -i-vorme, erandeid, eitust ning ajasõna järel sõnajärge.","g_use":"Õpilane kirjutab sõnumi ja 70–90-sõnalise loo ning räägib minevikust ja telefonis; kirjutamises ja rääkimises vähemalt 80 %."}},
  "a2b1-026": {"canDo":"Ma kirjutan Jaanile 80–100-sõnalise kirja pühapäevase lõuna menüüst ja ostunimekirjast koos kogustega.","goals":{"g_vocab":"Õpilane kasutab toidu ja koguse sõnu: toiduaine, kogus, nimekiri, pakk, purk, karp, liiter, köögivili, puuvili, värske.","g_read":"Õpilane mõistab Liisi blogist, turuvestlusest, poe raadioreklaamist ja kuulutustest, mida, kus ja kui palju osta.","g_notice":"Õpilane kasutab koguse ja arvu järel osastavat: liiter piima, kilo kartuleid, kolm tomatit, natuke juustu.","g_use":"Õpilane lepib Jaaniga kokku pühapäevase lõuna menüü, seletab plaani Helgile ja kirjutab Jaanile 80–100-sõnalise kirja ostunimekirjaga."}},
  "a2b1-027": {"canDo":"Ma helistan restorani, broneerin laua kogu perele ning küsin toitude ja allergiate kohta.","goals":{"g_vocab":"Õpilane kasutab kohviku ja restorani sõnu: menüü, päevapraad, eelroog, pearoog, magustoit, ettekandja, arve, eraldi, broneerima, jootraha.","g_read":"Õpilane saab aru kohviku ja poe lühiteadetest, tellimisest Kaneelis, raadiointervjuust ja restorani häälsõnumist.","g_notice":"Õpilane tellib ja palub viisakalt (Palun mulle…, Ma sooviksin…, Kas saaksime…?) ja kasutab -ks vormi: supiks, joogiks, magustoiduks.","g_use":"Õpilane tellib kohvikus allergiat arvestades, helistab restorani laua broneerimiseks ja kirjutab perele sõnumi."}},
  "a2b1-028": {"canDo":"Ma kirjutan 8–10-lauselise loo sellest, mis juhtus Markuse lõunaga, ja kasutan õigesti täis- ja osasihitist (sõi supi ära, ei söönud leiba).","goals":{"g_vocab":"Õpilane kasutab köögi sõnu: retsept, kaste, keetma, lõikama, maitsma, valmis, ära sööma, nõud, karp, reegel.","g_read":"Õpilane mõistab Sofia päevikut, Anna häälsõnumit retseptiga, raadiolugu toidu raiskamisest ja Markuse sõnumit: mis on tehtud ja mis jäi pooleli.","g_notice":"Õpilane eristab osastavat ja täissihitist: söön leiba – sõin leiva ära, tegi salati valmis; eituses on alati osastav: ei ostnud leiba.","g_use":"Õpilane jutustab, mis juhtus Markuse lõunaga, lepib köögikoosolekul kokku viis reeglit ja kirjutab sellest 8–10-lauselise loo."}},
  "a2b1-029": {"canDo":"Ma helistan toidukulleri klienditeenindusse, kirjeldan probleemi viisakalt ja nõuan lahendust, mis tingimuste järgi mulle kuulub.","goals":{"g_vocab":"Õpilane kasutab kaebuse sõnu: probleem, viga, kaebus, lahendus, vahetama, nõudma, allahindlus, hilinema, tellimus, kuller.","g_read":"Õpilane mõistab kohvikuvestlust, teateid, arvustusi ning tellimuse kinnitust ja tingimusi: mis läks valesti ja mida võib nõuda.","g_notice":"Õpilane kaebab nelja sammuga (pöördumine, probleem, palve, tänu) ja ühendab laused sõnadega aga, sest, kuna, et, vaid.","g_use":"Õpilane lahendab kohvikus vale tellimuse, helistab klienditeenindusse ja nõuab lahendust ning kirjutab firmale 80–100-sõnalise vastuse."}},
  "a2b1-030": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos B1 ülesannetega: loen, kuulan, kirjutan ja räägin toidu ja teeninduse teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_vocab":"Õpilane kasutab mooduli 6 toidu, koguse, teeninduse ja kaebuse sõnu ilma toeta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L3a, L4).","g_notice":"Õpilane kasutab õigesti osastavat koguse ja eituse järel ning täissihitist lõpetatud tegevuse puhul.","g_use":"Õpilane saab kirjutamises (W1b, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest."}},
  "a2b1-031": {"canDo":"Ma kirjutan haigeks jäänud kolleegile 80–100-sõnalise kirja: mis tööl juhtus, mida ma tema eest tegin ja mida ma soovitan.","goals":{"g_vocab":"Õpilane kasutab haiguse sõnu: haige, terve, palavik, köha, nohu, kurk, valutama, väsinud, puhkama, paranema, apteek.","g_read":"Õpilane saab aru Anna ja Sofia vestlusest, lastearsti kirjutisest, raadiosaatest gripi kohta ja Anna häälsõnumist: mis juhtus ja mida tuleb teha.","g_notice":"Õpilane eristab olekut ja muutust: olen haige – jäin haigeks, sain terveks, palavik läks kõrgeks (omastav + -ks).","g_use":"Õpilane kirjeldab haiget inimest, ütleb oma arvamuse, kirjutab ülemusele sõnumi, lepib kokku tööde jagamise ja kirjutab haigele kolleegile kirja."}},
  "a2b1-032": {"canDo":"Ma helistan Markuse eest perearstikeskusse, räägin, kuidas tema haigus on muutunud, ja broneerin talle sobiva aja.","goals":{"g_vocab":"Õpilane kasutab arsti ja apteegi sõnu: arst, perearst, hääl, kestma, tõsine, hingama, ravim, retsept, tablett, aeg; mõistab ravimi infolehte.","g_read":"Õpilane mõistab Markuse lugu, vestlust perearsti juures, teateid selle kohta, kuhu pöörduda, ja Markuse sõnumit.","g_notice":"Õpilane kasutab muutuse tegusõnu saava käändega: jäi kähedaks, läks hullemaks, muutus tugevamaks, sai terveks.","g_use":"Õpilane jutustab Markuse loo, kirjutab kliendile ametliku kirja, helistab tema eest perearstikeskusse, järjestab tööd ja kirjutab kaardi."}},
  "a2b1-033": {"canDo":"Ma lepin Markusega kokku kahenädalase uneplaani ja annan talle suuliselt nõu käskiva kõneviisiga (pane telefon ära, ära joo õhtul kohvi).","goals":{"g_vocab":"Õpilane kasutab vigastuse ja une sõnu: põlv, jalg, valu, kukkuma, harjutus, tõstma, ettevaatlik, uni, voodi, rahulik, keelama.","g_read":"Õpilane saab aru arsti, apteekri ja füsioterapeudi juhistest, lühikestest teadetest ja Markuse unepäevikust.","g_notice":"Õpilane moodustab käsu ja keelu sinale ja teile: pane – pange, võta – võtke, ära sõida – ärge sõitke.","g_use":"Õpilane annab Viktorile nõu, lahendab apteegis probleemi, vastab teemaküsimustele, lepib Markusega kokku uneplaani ja kirjutab talle vastuse."}},
  "a2b1-034": {"canDo":"Ma kirjutan kontori infolehte 80–100-sõnalise jutu sellest, kuidas mu harjumused kuu ajaga muutusid.","goals":{"g_vocab":"Õpilane kasutab harjumuste sõnu: harjumus, tervislik, liikuma, kõndima, eesmärk, tulemus, õnnestuma, jätkama, samm, alustama, soovitus.","g_read":"Õpilane mõistab Liisi kutset, Jaani lugu, raadiointervjuud harjumustest ja osalejate tulemusi ning leiab lõikudele pealkirja.","g_notice":"Õpilane ehitab jutu üles (probleem, esimene samm, raske hetk, tulemus, soovitus), ühendab laused sidesõnadega ja kasutab muutuse vormi.","g_use":"Õpilane küsitleb teisi, täidab küsimustiku, räägib uue kolleegiga ja kirjutab infolehte 80–100-sõnalise jutu ning selle parema versiooni."}},
  "a2b1-035": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos B1 ülesannetega: loen, kuulan, kirjutan ja räägin tervise teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L3a, L4).","g_notice":"Õpilane kasutab õigesti muutuse vormi (jäi haigeks, läks paremaks) ning käsku ja keeldu sinale ja teile.","g_use":"Õpilane saab kirjutamises (W1a, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest."}},
  "a2b1-036": {"canDo":"Ma helistan kooli huvijuhile, räägin, millest laps huvitub ja milles ta osaleda tahab, ning küsin huviringide kohta.","goals":{"g_vocab":"Õpilane kasutab kooli ja huviringide sõnu: klassijuhataja, õppeaine, hinne, ring, trenn, registreerima ning tegusõnu osalema, harjuma, valmistuma.","g_read":"Õpilane saab aru klassijuhataja kirjast, koolilehe intervjuust (Harno B1 lugemine 2), Olena ja Sofia vestlusest ning huviringide kaartidest.","g_notice":"Õpilane kasutab tegusõna rektsiooni ja kaassõnu: huvitub millest?, osaleb milles?, harjub millega?, valmistub milleks?, palub abi kellelt?, muret kelle pärast?","g_use":"Õpilane lepib kokku lapse huviringid, helistab huvijuhile, kirjutab klassijuhatajale sõnumi ja tutvustab end lastevanemate õhtul."}},
  "a2b1-037": {"canDo":"Ma kirjutan sõbrale 80–100-sõnalise kirja oma õppimisplaanist ja kasutan pärast tegusõnu õiget vormi: pean õppima, tahan osata.","goals":{"g_vocab":"Õpilane kasutab õppimise ja eksami sõnu: eksam, eesmärk, sooritama, tase, sõnavara, grammatika, test, tunnistus.","g_read":"Õpilane saab aru raadiosaatest (Harno B1 kuulamine 2), Anna ja Liisi lõunavestlusest, kontori infotahvlist ja keelekooli häälsõnumist.","g_notice":"Õpilane valib pean, hakkan, lähen, jään järel ma-vormi ning tahan, oskan, saan, proovin, on vaja järel da-vormi.","g_use":"Õpilane kirjutab kutse lõunaklubisse, seletab häälsõnumi sisu juhile, räägib oma õppimisplaanist ja kirjutab sõbrale kirja."}},
  "a2b1-038": {"canDo":"Ma kirjutan umbes 100-sõnalise jutu sellest, miks ma õpin, ja põhjendan oma valikuid sõnadega sest, kuna ja seepärast.","goals":{"g_vocab":"Õpilane kasutab põhjuse ja õppimisharjumuste sõnu: põhjus, tagajärg, väsinud, uni, harjumus, keskenduma, kasulik, vajalik ning -mine-nimisõnu.","g_read":"Õpilane leiab ajakirja loost, küsitluse diagrammist, keelekooli uudiskirjast ja Anna blogist põhjused ja tagajärjed.","g_notice":"Õpilane eristab põhjust ja tagajärge ning sõnajärge: Kuna päeval pole aega, õpib Anna õhtul; …, seepärast oli ta väsinud.","g_use":"Õpilane täidab küsimustiku põhjendustega (Harno B1 kirjutamine 1), lepib juhiga kokku tööaja ja kirjutab jutu „Miks ma õpin”."}},
  "a2b1-039": {"canDo":"Ma räägin oma õppimismurest ja lepin kokku lahenduse: millise kursuse või abi ma valin ja kuidas edasi õpin.","goals":{"g_vocab":"Õpilane kasutab õpimure sõnu: mure, lahendus, maha jääma, järele jõudma, puuduma, julgema, seletama, individuaalne, konsultatsioon.","g_read":"Õpilane saab aru häälsõnumitest, õpetaja nõuannetest, kursuste kuulutustest ja pakkumiste tabelist ning leiab neist sobiva lahenduse.","g_notice":"Õpilane kasutab rektsiooni (puudus millest, keskendub millele, palub abi kellelt) ja viisakat palvet: Kas te saaksite…? Kas ma võiksin…?","g_use":"Õpilane räägib oma õppimismurest, helistab keelekooli (Harno B1 rääkimine 2), lepib kokku õppimisplaani ja vastab õpetaja kirjale."}},
  "a2b1-040": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis koos B1 lugemis- ja kuulamisülesannetega ning kirjutan ja räägin B1 vormis; eesmärk on vähemalt 80 % igas osas ja võrdlus tundidega 1 ja 20.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L2, L3a).","g_notice":"Õpilane kasutab õigesti mooduli 8 sõnavara, rektsiooni ja kaassõnu, ma- ja da-vormi, sest- ja kuna-lauset ning varasemate moodulite vorme.","g_use":"Õpilane saab kirjutamises (W1b, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest ja võrdleb oma profiili tundidega 1 ja 20."}},
  "a2b1-041": {"canDo":"Ma kirjutan 90–110-sõnalise jätkuloo „Jaani otsus”: kellena Jaan töötab, mille eest ta vastutab ja mis edasi juhtub.","goals":{"g_vocab":"Õpilane kasutab ametite ja töö sõnu: amet, töökoht, vastutama, tegelema, hoolitsema, vahetus, palk, tööaeg, kuulutus, ülemus, ning tegija nimesid lõpuga -ja (müüja, tööandja).","g_read":"Õpilane mõistab Jaani lugu, Kadri raadiointervjuud ja Kadri kirja: kes kellena töötab, mille eest vastutab ja miks Jaan mõtleb töökoha vahetamisele; lahendab valiklünkteksti (Harno lugemine 3).","g_notice":"Õpilane kasutab -na-vormi (töötab kokana), vastutama/hoolitsema + omastav + eest ja tegelema + -ga ning valib valiklüngas vormi lause mõtte järgi.","g_use":"Õpilane kirjeldab ameteid pildil, arutab töökoha vahetamise poolt- ja vastuargumente ning kirjutab 90–110-sõnalise jätkuloo „Jaani otsus”."}},
  "a2b1-042": {"canDo":"Ma vastan kontori telefonile ja räägin helistajaga 2–3 minutit: ütlen ma-vormidega, kus kolleeg on ja millal ta tagasi tuleb (on kliendiga kohtumas, tuleb söömast), ja võtan sõnumi vastu.","goals":{"g_vocab":"Õpilane kasutab kontori ja telefoni sõnu: vastuvõtt, koosolek, koolitus, ladu, klient, tellimus, hinnapakkumine, sõnum, tagasi helistama, lõunapaus.","g_read":"Õpilane mõistab Sofia telefonikõnesid, raadiosaadet kodus töötamisest (Harno kuulamine 2), kontori nädalatahvlit ja kõneposti sõnumeid: kes on kus ja mida tuleb teha.","g_notice":"Õpilane eristab ma-vormi käändeid: läks kontrollima (kuhu), on kohtumas (kus), tuli söömast (kust), jäi saatmata (ilma); käib … -mas.","g_use":"Õpilane vastab kontori telefonile 2–3 minutit, ütleb tahvli järgi, kus kolleeg on, võtab sõnumi vastu ning kirjutab kutse ja teate."}},
  "a2b1-043": {"canDo":"Ma kirjutan töökuulutusele 90–110-sõnalise kandideerimiskirja: kes ma olen, mida oskan, miks see töö mulle sobib ja millal saan alustada.","goals":{"g_vocab":"Õpilane kasutab kandideerimise sõnu: kandideerima, kandidaat, kogemus, oskus, haridus, soovitus, tööandja, sobima, alustama, katseaeg, lugupidamisega.","g_read":"Õpilane mõistab raadio töökuulutuse numbreid, Anna kandideerimiskirja ülesehitust, karjäärinõustaja artiklit ja nelja töökuulutust.","g_notice":"Õpilane valib ma- või da-vormi tööväljendites (olen harjunud töötama, oskan teha, käisin õppimas), ühendab laused sidesõnadega ja kirjutab ametlikus registris.","g_use":"Õpilane täidab kandideerimisankeedi (Harno kirjutamine 1), lepib kokku, kes kuhu kandideerib, kirjutab 90–110-sõnalise kandideerimiskirja ja parandab selle hindamisjuhendi järgi."}},
  "a2b1-044": {"canDo":"Ma räägin töövestlusel oma kogemusest ja oskustest, toon iga tugevuse kohta näite, esitan ise kaks küsimust ja lepin kokku, millal tööd alustan.","goals":{"g_vocab":"Õpilane kasutab töövestluse sõnu: tugevus, nõrkus, näide, meeskond, täpne, paindlik, juhendaja, kutse, kokkulepe, lahkuma.","g_read":"Õpilane mõistab kutset töövestlusele, Merike vastust, Anna töövestluse salvestust, nõuandeid ja direktori häälsõnumit: mida küsitakse ja mis on Jaani probleem.","g_notice":"Õpilane ehitab vastuse väide + näide + seos ja kasutab ma-vorme (olen harjunud töötama, käisin kursusel õppimas, ükski tellimus ei jäänud täitmata); parandab tüüpvead.","g_use":"Õpilane vastab töövestluse küsimustele 3–4 lausega, lepib ideekaardi abil kokku (Harno rääkimine 1), teeb telefonivestluse ja leiab endise ülemusega kompromissi."}},
  "a2b1-045": {"canDo":"Ma sooritan mooduli eksami Harno B1 vormis (lühendatud): kirjutan, loen, kuulan ja räägin töö teemal ning saan igas osas vähemalt 80 % punktidest.","goals":{"g_read":"Õpilane saab lugemises (R1–R4) ja kuulamises (L1–L4) vähemalt 80 % punktidest: töökuulutused, artikkel, valiklünktekst, fraasid tekstis, teated, raadiolugu, vestlus ja intervjuu.","g_notice":"Õpilane kasutab õigesti -na-vormi, vastutama … eest, tegelema …-ga, ma-vormi käändeid ning ma- ja da-vormi tööväljendites.","g_use":"Õpilane saab kirjutamises (teade W1b, jutt W2a) ja rääkimises (S0, S1a, S1b, S2) vähemalt 80 % punktidest."}},
  "a2b1-046": {"canDo": "Ma helistan rongifirma infotelefonile, vahetan pere piletid ja selgitan onule telefonis tema teekonna ümberistumisega.", "goals": {"g_vocab": "Õpilane kasutab rongireisi sõnu: rong, pilet, jaam, väljuma, saabuma, ümber istuma, vagun, istekoht, sõiduplaan, edasi-tagasi, hilinema, reisija.", "g_read": "Õpilane saab aru Sofia ja Jaani kõnest, rongisaatja raadiointervjuust, jaama teadetest ja teadaannetest ning Viktori häälsõnumist: ajad, hinnad, perroonid ja reeglid.", "g_notice": "Õpilane kasutab sõiduinfos kohavorme: väljub Tallinnast / Tapalt, saabub Tartusse / Tapale, istub ümber Tapal, ootab ooteruumis.", "g_use": "Õpilane vahetab telefonis rongipiletid, lahendab rongisaatjaga kohtade probleemi, selgitab onule teekonda ja kirjutab emale 50–70-sõnalise sõnumi."}},
  "a2b1-047": {"canDo": "Ma loen reisipakkumisi ja ülemuse kirja, võrdlen võimalusi ja kirjutan ülemusele 80–100-sõnalise vastuse reisiplaani ja kuludega.", "goals": {"g_vocab": "Õpilane kasutab reisi planeerimise sõnu: töölähetus, näitus, eelarve, lend, lennujaam, broneerima, hotell, hommikusöök, soodne, mugav, võrdlema, kulu.", "g_read": "Õpilane leiab reisiblogist, kuulutustest, näituse infost ja Liisi kirjast hinnad, ajad ja tingimused ning saab aru hotelli telefonikõnest.", "g_notice": "Õpilane võrdleb ja põhjendab: eelistan bussi lennukile, kumb on parem, mõlemad, kumbki, pigem … kui, seepärast; esitab hotellile viisakaid küsimusi.", "g_use": "Õpilane lepib Markusega plaani kokku, kaitseb seda Liisi ees ja kirjutab Liisile 80–100-sõnalise vastuse plaani ja kuludega."}},
  "a2b1-048": {"canDo": "Ma räägin reisiloo õiges järjekorras, ütlen enneminevikus, mis oli enne juhtunud (laev oli juba lahkunud), ja lepin žüriis kokku parima loo.", "goals": {"g_vocab": "Õpilane kasutab reisiloo sõnu: sadam, laev, lahkuma, jõudma, märkama, unustama, selguma, kinnitama, õnneks, kahjuks, lõpuks, meenutama.", "g_read": "Õpilane mõistab Anna blogist, raadiosaatest „Teel juhtunud” ja kuulajate lugudest, mis juhtus enne ja mis pärast.", "g_notice": "Õpilane moodustab enneminevikku (oli lahkunud, olime unustanud, polnud kinnitanud) ja eristab seda lihtminevikust ja täisminevikust.", "g_use": "Õpilane jutustab oma reisiloo kaks korda, vastab reisimise teemaküsimustele, lepib žüriis kokku parima loo ja kirjutab saate kodulehele umbes 100-sõnalise jutu."}},
  "a2b1-049": {"canDo": "Ma kirjutan sõbrale 80–100-sõnalise kirja tema reisi plaaniga: sõidud, ööbimine, hinnad ja üks hea nõuanne.", "goals": {"g_vocab": "Õpilane kasutab reisi korraldamise sõnu: ühendus, peatus, bussijaam, ööbima, külalistemaja, vaatamisväärsus, kohver, pagas, tühistama, viimane, piisama, soovitus.", "g_read": "Õpilane mõistab Lena häälsõnumit, Markuse lugu Viljandist, linnade tutvustust, Sofia ja Lena sõnumeid ning sõiduplaani ja hinnakirja.", "g_notice": "Õpilane kasutab enneminevikku põhjuses ja hoiatuses: Ma ei teadnud, et buss oli juba läinud; Kui me jõudsime, oli … juba …; sest öösel oli lund sadanud.", "g_use": "Õpilane helistab külalistemajja, lepib Lenaga plaani kokku ja kirjutab Lenale 80–100-sõnalise isikliku kirja reisiplaaniga."}},
  "a2b1-050": {"canDo": "Ma sooritan reisiteemalise mooduli eksami Harno B1 vormis lühendatud pikkusega: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_read": "Õpilane saab lugemises (28 punkti) ja kuulamises (23 punkti) vähemalt 80 % punktidest.", "g_notice": "Õpilane kasutab õigesti kohavorme sõiduinfos, enneminevikku ja valiku põhjendamise sõnu (eelistan bussile, kumb, mõlemad).", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}},
  "a2b1-051": {"canDo": "Ma loen poe pakkumisi, võrdlen hindu ja lepin poes kokku, mida eelarve piires osta.", "goals": {"g_vocab": "Õpilane kasutab ostlemise sõnu: hind, soodustus, pakkumine, garantii, kehtima, tšekk, müüja, sularaha, kokku, eelarve, tagastama, proovima.", "g_read": "Õpilane loeb poe Nutikas pakkumisi, soodusmüügi artiklit ja spordipoe saabaste kaarte ning saab aru Sofia jutust ja kaubanduskeskuse teadetest.", "g_notice": "Õpilane küsib poes hinda, soodustust ja varianti (Kas seda on ka suuruses 34? Kas sellele on soodustust?) ja arvutab protsendi: 20 % odavam.", "g_use": "Õpilane leiab infolüngaga soodsama poe, lepib Oskariga 60 euro piires saabaste valiku kokku, salvestab Kadrile häälsõnumi ja kirjutab talle 60–80-sõnalise sõnumi."}},
  "a2b1-052": {"canDo": "Ma kirjutan Helgile 80–100-sõnalise kirja, milles võrdlen kaht autot ja põhjendan, miks pere ühe valis.", "goals": {"g_vocab": "Õpilane kasutab autoostu sõnu ja sidesõnu: kasutatud, kuulutus, kütus, pagasiruum, mugav, soodne, võrdlema, proovisõit, kauplema, otsustama, kindlustus, leping; sest, kuigi, seepärast.", "g_read": "Õpilane loeb Kadri kirja, auto- ja rattakuulutusi ning Karini e-kirja ja saab aru Jaani kõnest müüjaga: hinnad, aastad ja tingimused.", "g_notice": "Õpilane moodustab kesk- ja ülivõrde (odavam, väiksem, parem, rohkem, kõige parem), võrdleb kahel viisil (odavam kui Škoda = Škodast odavam) ja seob laused sidesõnadega.", "g_use": "Õpilane kirjutab müüjale viisaka sõnumi, täidab autoportaali küsimustiku, kaupleb müüjaga hinna üle ja kirjutab Helgile 80–100-sõnalise kirja auto valikust."}},
  "a2b1-053": {"canDo": "Ma kirjutan e-poele 80–100-sõnalise kaebuse: mida tellisin, mis juhtus ja mida soovin, ning kasutan kesksõnu (tellitud jope, makstud raha).", "goals": {"g_vocab": "Õpilane kasutab tagastamise sõnu: katkine, parandama, remont, vahetama, karp, laadija, tellimus, kaebus, asendama, tasuta, teenindus, kasutamata.", "g_read": "Õpilane saab aru raadiosaate „Tarbija tund” nõuannetest ja e-poe Lasteriie selgitustest ning loeb poe tagastamise ja garantii tingimusi.", "g_notice": "Õpilane kasutab kesksõnu nimisõna ees: ostetud kaup, makstud arve, avatud pakend, parandatud telefon, kehtiv garantii, soovitatav hind.", "g_use": "Õpilane seletab sõbrale, mida teeninduses öeldi, lahendab teeninduslauas kõrvaklappide probleemi, helistab e-poodi ja kirjutab poele 80–100-sõnalise kaebuse."}},
  "a2b1-054": {"canDo": "Ma helistan poe juhatajale, selgitan garantiiprobleemi, põhjendan oma nõuet ja lepin kokku lahenduse.", "goals": {"g_vocab": "Õpilane kasutab kaebuse sõnu: nõue, nõudma, juhataja, tõend, niiskus, lahendus, rahul, soovitama, arvustus, õigus, vastama, tähtaeg.", "g_read": "Õpilane saab aru töökoja häälsõnumist ja raadio tarbijanõustaja nõuannetest ning loeb poe teateid, remondiakte ja garantiitingimusi.", "g_notice": "Õpilane kasutab kaebuses kesksõnu (parandatud telefon, makstud summa, täidetud leht) ja viisakat, kuid kindlat teie-käsku: parandage, vastake, saatke, ärge võtke.", "g_use": "Õpilane valib järgmise sammu, täidab garantiinõude vormi, räägib poe juhatajaga telefonis, salvestab kokkuvõtte ja kirjutab poe kodulehele arvustuse."}},
  "a2b1-055": {"canDo": "Ma sooritan raha, ostlemise ja teenuste mooduli eksami Harno B1 vormis täispikkuses: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu poe, panga, töökoja ja e-poe kohta: soodustus, garantii, tšekk, kauplema, tagastama, tellimus, kaebus, tõend, arvustus.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_notice": "Õpilane kasutab õigesti võrdlust, kesksõnu nimisõna ees ja viisakat teie-käsku.", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}},
  "a2b1-056": {"canDo": "Ma saan kuuldust aru: kuulan ilmateadet ja onu häälsõnumit ning kirjutan sõbrale 80–100-sõnalise kirja, kuidas ilm meie jaanipäeva plaani muudab.", "goals": {"g_vocab": "Õpilane kasutab ilma sõnu: ilmateade, palav, jahe, äike, välk, tuul, kraad, hoiatus, niiske, pilvine, temperatuur, tõusma; kraadid, kellaajad ja tuule kiirus kuuldes.", "g_read": "Õpilane saab aru raadio ilmateadetest, meteoroloogi raadiosaatest, ilmateenistuse lehest ja Viktori häälsõnumist: ajad, kraadid, hoiatused ja nõuanded.", "g_notice": "Õpilane ütleb, kuidas ilm muutub (läheb jahedamaks, muutub tuuliseks, jääb soojaks) ja kasutab ilmateate vorme oodatakse, soovitatakse, tõuseb … kraadini.", "g_use": "Õpilane kirjeldab ilma, lepib infolüngaga kokku sõiduaja, helistab seltsimajja, salvestab häälsõnumi ja kirjutab sõbrale 80–100-sõnalise kirja."}},
  "a2b1-057": {"canDo": "Ma loen rabaloo ja kirjutan sellele umbes 100-sõnalise lõpu, kus sündmused on õiges järjekorras (kui, enne kui, pärast seda, kui).", "goals": {"g_vocab": "Õpilane kasutab looduse ja äikese sõnu: raba, laudtee, vaatetorn, müristama, mänd, kummik, ronima, kiirustama, kukkuma, märg, otsima, peitu minema.", "g_read": "Õpilane loeb rabalugu ja artiklit äikesest looduses, saab aru Oskari jutust ja matkaradade teadetest ning leiab Oskari päevikust puuduvad lauseosad.", "g_notice": "Õpilane jutustab kui-, enne kui-, pärast seda, kui- ja samal ajal kui -lausetega (pealauses tegusõna kohe) ning kasutab lihtminevikku ja enneminevikku.", "g_use": "Õpilane jutustab loo kaks korda, vastab teemaküsimustele, lepib kokku, kust Mukit otsida, salvestab loo Mia silmadega ja kirjutab loole umbes 100-sõnalise lõpu."}},
  "a2b1-058": {"canDo": "Ma helistan kindlustusse, selgitan põhjuse ja tagajärjega, mis tormis juhtus (tormi tõttu, seepärast, nii et), ja lepin kokku järgmised sammud.", "goals": {"g_vocab": "Õpilane kasutab tormi sõnu: torm, kask, katus, elekter, rike, kaev, sügavkülmik, kahju, põhjus, tagajärg, tõttu, seepärast; tormine, kuumus, pimedus.", "g_read": "Õpilane saab aru tormiuudisest, Jaani ja Viktori kõnest, vallalehe loost ning loeb kindlustuse tingimusi ja kahjude nimekirja.", "g_notice": "Õpilane seob põhjuse ja tagajärje (sest, kuna, … tõttu, … pärast, seepärast, seetõttu, nii et) ja paneb pärast seepärast / seetõttu ning kuna-lause järel tegusõna kohe.", "g_use": "Õpilane räägib tormiööst kolm korda, seletab Sofiale, lepib naabriga kokku, helistab kindlustusse, salvestab Helgile häälsõnumi ja vastab kindlustuse kirjale."}},
  "a2b1-059": {"canDo": "Ma räägin oma arvamusest keskkonnasõbralike harjumuste kohta (arvamus, põhjus, näide) ja lepin naabritega kokku, mida meie hoovis ära teeme.", "goals": {"g_vocab": "Õpilane kasutab keskkonna sõnu ja rektsiooni: keskkond, keskkonnasõbralik, prügi, sorteerima, ettepanek, arvamus, kokkulepe; hoolima millest, loobuma millest, osalema millel, nõustuma millega.", "g_read": "Õpilane saab aru keskkonnanõustaja raadiointervjuust ja naabrite häälsõnumitest ning loeb teenuste kuulutusi ja naabrite ettepanekuid.", "g_notice": "Õpilane ütleb arvamuse mudeliga arvamus + põhjus + näide, nõustub ja kahtleb viisakalt ning kasutab ühistu teates umbisikulist vormi (pannakse, ei panda).", "g_use": "Õpilane küsitleb kolme inimest, ütleb arvamuse viie väite kohta, teeb ühistu teate viisakaks, lepib koosolekul kokku hoovi plaani, salvestab kokkuvõtte ja kirjutab talgukutse."}},
  "a2b1-060": {"canDo": "Ma sooritan esimese täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; vahekontrolli lävi on 60 % ja eesmärk 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu ilma, looduse, tormi ja keskkonna kohta: ilmateade, äike, jahe, raba, laudtee, torm, tõttu, seepärast, keskkond, sorteerima, ettepanek, kokkulepe.", "g_read": "Õpilane saab lugemises (33 punkti) vähemalt 20 ja kuulamises (30 punkti) vähemalt 18 punkti; eesmärk on 80 % (27 ja 24 punkti).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: ilma muutumine (läheb jahedamaks), kui- ja enne kui -laused, põhjus ja tagajärg (tõttu, seepärast + tegusõna), rektsioon.", "g_use": "Õpilane saab kirjutamises ja rääkimises (kumbki 20 punkti) vähemalt 12 punkti; eesmärk on 16 punkti; alla vahekontrolli jäänud osale teeb õpetaja moodulites 13–15 järeleaitamise plaani."}},
  "a2b1-061": {"canDo": "Ma loen ühistu teadet ja remondigraafikut ning lepin naabritega kokku, kuidas remondiaja mured lahendada: palun abi, teen ettepaneku ja keeldun viisakalt.", "goals": {"g_vocab": "Õpilane kasutab remondi ja naabrisuhete sõnu: remont, ehitaja, müra, trepikoda, rõdu, kelder, palve, paluma, keelduma, nõus, valmis, vaikus; remondiaja teenuste kuulutused.", "g_read": "Õpilane loeb ühistu esimehe kirja, linnaosa lehe nõuandeid ning remondigraafikut ja ühistu otsuseid ning saab aru maja koosolekust töödejuhatajaga.", "g_notice": "Õpilane palub, teeb ettepaneku ja keeldub (kahjuks + põhjus + uus pakkumine) ning annab palve edasi: palub / soovitab / keelab / lubab teha, on nõus / valmis tegema.", "g_use": "Õpilane tutvustab end uutele naabritele, kirjutab kaheksa minutit naabritest, lepib infolüngaga kokku, millal Heljut aidata, lepib naabritega kokku Karli mure lahenduse, salvestab Karlile häälsõnumi ja kirjutab maja vestlusesse teate."}},
  "a2b1-062": {"canDo": "Ma saan kuuldust aru ja helistan hotelli: palun ja küsin tingiva kõneviisiga viisakalt (sooviksin, kas te saaksite, kas oleks võimalik) ning lahendan broneeringu probleemi.", "goals": {"g_vocab": "Õpilane kasutab reisi ja hotelli sõnu: broneerima, tuba, vastuvõtt, administraator, praam, järjekord, sadam, pilet, hommikusöök, vabandama, võimalik, allahindlus.", "g_read": "Õpilane saab aru Kadri kõnest hotelli, raadiointervjuust viisakusest ja hotelli juhataja häälsõnumist ning loeb hotelli teateid ja juhataja kirja.", "g_notice": "Õpilane moodustab tingiva kõneviisi kõigis isikutes (saaksin, saaksid, saaks, saaksime, saaksite, saaksid; oleks, võiksime) ja muudab käsu viisakaks palveks või sooviks.", "g_use": "Õpilane kirjeldab puhkusefotot, muudab ebaviisaka sõnumi viisakaks, kirjutab üles viisakad palved, vastab küsimusele „Mida sa teeksid?”, helistab hotelli juhatajale, salvestab Helgile häälsõnumi ja täidab hotelli küsimustiku."}},
  "a2b1-063": {"canDo": "Ma loen maja vestlust ja teadet, eristan kindlat infot kuuldud jutust (ta olevat …) ja kirjutan umbes 100-sõnalise jutu sellest, kuidas kuulujutt sündis.", "goals": {"g_vocab": "Õpilane kasutab kuulujutu ja tüli sõnu: kuulujutt, väidetavalt, süüdistama, tüli, arusaamatus, tõde, tegelikult, uskuma, haukuma, jälg, värvima, õiglane; rääkimise tegusõnade rektsioon.", "g_read": "Õpilane loeb maja vestlust, kolme tunnistaja juttu ja Urmase teadet ning saab aru Karli kõnest: kes mida ise nägi ja mis tegelikult juhtus.", "g_notice": "Õpilane eristab kindlat väidet ja kuuldud juttu ning moodustab kaudse kõneviisi oleviku ja mineviku (olevat, tegevat, olevat teinud, ei olevat) ja kasutab sõnu väidetavalt, kuuldavasti, … sõnul.", "g_use": "Õpilane räägib kuulujutust kolm korda, jutustab oma loo, annab Sofiale edasi, mida räägitakse, räägib solvunud Karliga, salvestab loo sõbrale ja kirjutab jutu „Kuidas kuulujutt sündis”."}},
  "a2b1-064": {"canDo": "Ma kuulan mõlemat poolt, aitan kolleegidel kokku leppida ja kirjutan ülemusele 80–100-sõnalise kirja, mida otsustati ja miks.", "goals": {"g_vocab": "Õpilane kasutab kokkuleppe ja kontori sõnu: koosolek, kompromiss, seisukoht, lahendus, otsus, vaidlema, solvuma, aken, konditsioneer, allergia, rahulik, kokkuvõte; numbrid, kuupäevad ja summad kuuldes.", "g_read": "Õpilane saab aru Markuse ja Kristjani häälsõnumitest ning Liisi sõnumist puhkuselt ja loeb Anna näidiskirja ning tööelu ajakirja nõuandeid.", "g_notice": "Õpilane annab edasi teise inimese seisukoha (Markuse sõnul, Kristjan ütles, et…, olevat öelnud), ehitab kirja lõikudest ja seob laused (seepärast, kuna, pärast seda, kui, kokkuvõttes).", "g_use": "Õpilane ütleb oma arvamuse, küsitleb kolme inimest, vastab teemaküsimustele, juhib Markuse ja Kristjani koosolekut, salvestab Liisile kokkuvõtte, teeb kirja plaani ja kirjutab Liisile 80–100-sõnalise kirja."}},
  "a2b1-065": {"canDo": "Ma sooritan suhtlemise ja probleemilahenduse mooduli eksami Harno B1 vormis täispikkuses: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu remondi, hotelli, kuulujutu ja kokkuleppe kohta: remont, müra, palve, keelduma, broneerima, vastuvõtt, allahindlus, kuulujutt, tegelikult, seisukoht, kompromiss, kokkulepe.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_notice": "Õpilane kasutab õigesti mooduli vorme: palub teha / on nõus tegema, tingiv kõneviis viisakas palves, kaudne kõneviis (olevat, olevat teinud) ja siduvad sõnad kirjas.", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}},
  "a2b1-066": {"canDo":"Ma jutustan 3 minutit mineviku sündmusest selges järjekorras ja lisan aja, koha, inimesed ja tunde.","goals":{"g_vocab":"Õpilane kasutab jutustamise sõnu: mälestus, jutustama, ehitama, valmis, läbi lugema, ära tegema, parandama, katus, lõpuni.","g_read":"Õpilane mõistab Viktori intervjuud saunast, Helgi kahte mälestust ja õpetaja Kristeli näidislugu klassi raamatus.","g_notice":"Õpilane näitab lihtminevikus, et tegevus sai lõpuni: luges raamatu läbi, sõi piruka ära, tegi sauna valmis.","g_use":"Õpilane jutustab taskuhäälingu intervjuus oma loo, räägib selle algusest lõpuni ja kirjutab klassi raamatusse 10–12 lauset."}},
  "a2b1-067": {"canDo":"Ma eristan elukogemust (olen käinud) ja konkreetset sündmust (käisin eile) ning küsin „Kas sa oled kunagi…?”.","goals":{"g_vocab":"Õpilane kasutab kogemuse sõnu: kogemus, kunagi, esimest korda, juba, veel, lendama, proovima, võitma, julgema, välismaa.","g_read":"Õpilane mõistab Oskari kõnet Helgile, Sofia ajaveebi postitust, Rasmuse intervjuud Viktoriga ja Kristeli kuulutust elavast raamatukogust.","g_notice":"Õpilane eristab kogemust täisminevikus (olen lennanud, ei ole kunagi juhtinud) ja ajaga sündmust lihtminevikus (lendasin 1999. aastal).","g_use":"Õpilane on lugude õhtul elav raamat, vastab lugejate küsimustele, tutvustab end ja kirjutab Kristelile oma kogemustest."}},
  "a2b1-068": {"canDo":"Ma seon sündmused jutustuseks, kasutan vähemalt seitset eri sidesõna ja panen pärast neid tegusõna teisele kohale.","goals":{"g_vocab":"Õpilane kasutab ajajoone sõnu: sündima, lõpetama, abielluma, kolima, pärast seda, hiljem, varsti, samal ajal, enne kui.","g_read":"Õpilane mõistab Helgi elulugu ja tema häälsõnumit ajajoone vigadest ning järjestab sündmused ajajoonele.","g_notice":"Õpilane paneb pärast lause alguse ajasõna või kui-lauset tegusõna teisele kohale: Pärast keskkooli läksin Tartusse.","g_use":"Õpilane teeb näituseks oma ajajoone, tutvustab seda külastajatele ja kirjutab selle kõrvale 10–12-lauselise eluloo."}},
  "a2b1-069": {"canDo":"Ma jutustan meeldejäävast kogemusest neljas osas: sündmus, tunne, põhjus ja järeldus.","goals":{"g_vocab":"Õpilane kasutab tundesõnu: meeldejääv, juhtuma, piinlik, üllatunud, arusaamatus, paanika, pisarad, järeldus.","g_read":"Õpilane mõistab Sofia lugu, Viktori mälestust, raadiosaadet „Minu lugu” ja lugude õhtu kava ning leiab sündmuse, tunde ja järelduse.","g_notice":"Õpilane ehitab loo neljast osast (sündmus, tunne, põhjus, järeldus) ja kasutab loos kolme minevikku.","g_use":"Õpilane kirjutab klassi raamatusse 10–12-lauselise mälestusloo, esitab selle lugude õhtul aulas ja vastab saali küsimustele."}},
  "a2b1-070": {"canDo":"Ma sooritan mineviku ja kogemuste eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli põhisõnu: ajajoone sõnad, kogemuse sõnad ja tunded.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane valib õigesti lihtmineviku ja täismineviku ning seob loo ajajoone sõnadega.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-071": {"canDo":"Ma räägin tulevikust loomulike eesti konstruktsioonidega: olevik + ajasõna ja hakkama + ma-vorm.","goals":{"g_vocab":"Õpilane kasutab tuleviku sõnu: tulevik, hakkama, kavatsema, plaanima, uuel aastal, lubadus, järgmisel aastal, varsti.","g_read":"Õpilane mõistab pere aastavahetuse vestlust, Oskari kirjandit, ajakirja artiklit uue aasta lubadustest ja keelekooli kursuse infot.","g_notice":"Õpilane räägib tulevikust oleviku ja ajasõnaga, hakkama + ma-vormiga, kavatsema + da-vormiga ning muutusest saama + -ks.","g_use":"Õpilane koostab õpetaja Maretiga kevade õppimise plaani, jätab Jaanile häälsõnumi ja kirjutab Maretile oma plaanist."}},
  "a2b1-072": {"canDo":"Ma kirjeldan kolme eesmärki, põhjendan neid ja nimetan iga eesmärgi juurde kaks sammu.","goals":{"g_vocab":"Õpilane kasutab eesmärgi sõnu: eesmärk, soov, unistus, samm, selleks, saavutama, harjutama, olgu peale, tähtaeg.","g_read":"Õpilane mõistab pere jutugruppi, Viktori Peipsi-sõidu plaani, Markuse arenguvestlust ja Tuul Logistika arenguvestluse juhendit.","g_notice":"Õpilane sõnastab soovi (tahaksin), eesmärgi ja sammu (Selleks pean…) ning mõistab möönvat kõneviisi: olgu, tulgu, tehku.","g_use":"Õpilane peab arenguvestluse, tutvustab meeskonnale oma eesmärke ja kirjutab Liisile kaks eesmärki sammude ja tähtaegadega."}},
  "a2b1-073": {"canDo":"Ma moodustan õigesti vähemalt kuus reaalset tingimuslauset (kui + olevik, (siis) …) ja teen plaani A ja B.","goals":{"g_vocab":"Õpilane kasutab tingimuse sõnu: kui, siis, tingimus, juhul kui, plaan B, laager, koduigatsus, lõpumäng.","g_read":"Õpilane mõistab Oskari ja isa vestlust, treeneri laagrikirja, ajalehe nõuandeid ning ilmateadet ja Viktori kõnet Peipsi äärest.","g_notice":"Õpilane moodustab reaalse tingimuslause olevikuga (Kui sajab, treenime sees) ja paneb pärast kui-osa koma ja kohe tegusõna.","g_use":"Õpilane teeb Kadriga Viktori homseks sõidupäevaks plaani A ja B, räägib selle blogivideos ja kirjutab pere jutugruppi."}},
  "a2b1-074": {"canDo":"Ma põhjendan oma plaani mudeliga otsus + kaks põhjust + näide + kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab põhjendamise sõnu: otsus, esiteks, teiseks, näiteks, kuigi, kokkuvõttes, ettepanek, toetama, veenma.","g_read":"Õpilane mõistab Jaani vestlust Helgiga, tema ettepanekut kooli majandusjuhatajale ja mentor Eha juhendit tegevusplaani kohta.","g_notice":"Õpilane põhjendab plaani mudeliga otsus + esiteks / teiseks + näide + kokkuvõte ning mõistab kuigi-lauset vastuväites.","g_use":"Õpilane tutvustab mentorile oma päris tegevusplaani, vastab küsimustele ja kirjutab plaani eesmärgi, sammude, tähtaegade ja plaaniga B."}},
  "a2b1-075": {"canDo":"Ma sooritan tuleviku ja plaanide eksami Harno B1 vormis: lugemine, kuulamine, kirjutamine ja rääkimine (eesmärk vähemalt 60% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli põhisõnu: tuleviku ajasõnad, eesmärgi sõnad ja põhjendamise sõnad.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 60% punktidest.","g_notice":"Õpilane kasutab õigesti tulevikku, da-vormi, kui-lauseid ja põhjenduse mudelit.","g_use":"Õpilane saab kirjutamises ja rääkimises vähemalt 60% punktidest."}},
  "a2b1-076": {"canDo":"Ma avaldan igapäevastel teemadel arvamust täislausega ja annan vähemalt viis vastust kujul arvamus + põhjus.","goals":{"g_vocab":"Õpilane kasutab arvamuse sõnu: minu arvates, tunduma, kindel, põhjus, ekraan, nutitelefon, otsustama, reegel.","g_read":"Õpilane mõistab Metsade õhtusöögi vestlust, uudisportaali uudist, vanemate foorumit ja Kase kooli direktori kirja.","g_notice":"Õpilane ütleb arvamuse kindluse järgi (olen kindel, ma arvan, mulle tundub) ja paneb pärast „minu arvates” tegusõna kohe.","g_use":"Õpilane arutab lastevanemate koosolekul direktori ettepanekut, peab sõnavõtu ja kirjutab klassijuhatajale arvamuse põhjuste ja näitega."}},
  "a2b1-077": {"canDo":"Ma võrdlen kahte võimalust nelja võrdlusega (keskvõrre + kui, võrreldes + -ga, samas) ja põhjendan oma valikut.","goals":{"g_vocab":"Õpilane kasutab võrdlemise sõnu: võrdlema, võrreldes, kaugtöö, kontor, samas, eelis, puudus, variant, mugavam, säästma.","g_read":"Õpilane mõistab Sofia blogi kaugtööst, raadiosaadet „Päevateema” ning Anna ja Markuse arutelu Liisi kahe variandi üle.","g_notice":"Õpilane võrdleb keskvõrde + kui, võrreldes + -ga, sama … kui ja ülivõrdega: kodus on vaiksem kui kontoris.","g_use":"Õpilane esitab Liisile tiimi kaugtöö ettepaneku, räägib Jelenale häälsõnumis, mida otsustati, ja kirjutab Liisile ettepaneku."}},
  "a2b1-078": {"canDo":"Ma ehitan kolm lühikest argumenti skeemi järgi: arvamus → põhjus → näide → järeldus, suuliselt ja lõiguna.","goals":{"g_vocab":"Õpilane kasutab argumendi sõnu: põhjendama, näiteks, järeldus, seepärast, seega, hoov, mänguväljak, parkimiskoht, hääletama.","g_read":"Õpilane mõistab linnaosa uudist, raadiouudiseid ja Ülle raadiosaate kodulehte tänavate kiirusest koos kuulajate kommentaaridega.","g_notice":"Õpilane ehitab argumendi arvamus → põhjus → näide → järeldus, paneb pärast seega tegusõna kohe ja täpsustab kes- / mis-lausega.","g_use":"Õpilane helistab Ülle otsesaatesse kesklinna 30 km/h kiirusest ja kirjutab saate kodulehele kahe argumendiga kommentaari."}},
  "a2b1-079": {"canDo":"Ma osalen 4–5-minutilises arutelus: nõustun, vaidlen osaliselt vastu, toon näite ja esitan vastuküsimuse.","goals":{"g_vocab":"Õpilane kasutab arutelu sõnu: arutelu, nõus, vastu, ettepanek, kompromiss, kokkulepe, koosolek, otsus, kokkuvõte.","g_read":"Õpilane mõistab raadioarutelu, ühistute ajakirja nõuandeid, Kadri ja Karli vestlust ning naabermaja koosoleku protokolli.","g_notice":"Õpilane ütleb arvamuse tingivas (arvaksin, oleks parem, võiksime), nõustub, vaidleb osaliselt vastu ja esitab vastuküsimuse.","g_use":"Õpilane arutab elanike koosolekul hoovi tulevikku, aitab jõuda otsuseni, teeb kokkuvõtte ja kirjutab maja grupile arvamusloo."}},
  "a2b1-080": {"canDo":"Ma lahendan B1 eksami vormis lugemise, kuulamise, kirjutamise ja rääkimise ülesanded; kokku vähemalt 70% ning kirjutamises ja rääkimises vähemalt 65%.","goals":{"g_vocab":"Õpilane kasutab mooduli arvamuse, võrdlemise ja põhjendamise sõnavara eksamiülesannetes ilma toeta.","g_read":"Õpilane lahendab B1 lugemise ja kuulamise ülesanded (kuulutused, 250–300-sõnaline artikkel, lünktekstid, teated, intervjuu) vähemalt 70% ulatuses.","g_notice":"Õpilane kasutab õigesti mooduli grammatikat: sõnajärg pärast „minu arvates”, keskvõrre, kuna/seetõttu, des-vorm, umbisikuline ja tingiv vorm, kaudne kõne.","g_use":"Õpilane kirjutab 50-sõnalise teate ja 100–130-sõnalise arvamuskirja, räägib 2 minutit teemakaardi järgi ja jõuab paarilisega kokkuleppele; kirjutamises ja rääkimises vähemalt 65%."}},
  "a2b1-081": {"canDo":"Ma leian teadetest, kuulutustest ja 200–250-sõnalisest artiklist vajaliku info ning vastan õigesti vähemalt 75% küsimustest.","goals":{"g_vocab":"Õpilane kasutab teadete sõnu: teade, kuulutus, avatud, suletud, registreeruma, tasuta, keelatud, korteriühistu, tähtaeg.","g_read":"Õpilane leiab vajaliku info trepikoja teadetest, raadio kohalikest uudistest ja Tiina ühistu kirjast.","g_notice":"Õpilane mõistab ja moodustab teadete umbisikulisi vorme olevikus ja minevikus: vahetatakse, suletakse, vahetati, suleti.","g_use":"Õpilane selgitab uuele naabrile Ruslanile ühistu kirja, jätab Jaanile häälsõnumi ja kirjutab Ruslani nimel Tiinale 50-sõnalise sõnumi."}},
  "a2b1-082": {"canDo":"Ma kirjutan 50-sõnalise teate nelja punktiga, täidan 10 küsimusega ankeedi ja kirjutan 100–130-sõnalise e-kirja, mis katab kõik punktid.","goals":{"g_vocab":"Õpilane kasutab kirja sõnu: pöördumine, lugupeetud, lugupidamisega, seoses, vastus, ankeet, täitma, nõuanne, mure.","g_read":"Õpilane mõistab Mareti häälsõnumit, Helgi kirja, Sofia ja Jaani telefonivestlust ning keelekooli kirja proovieksamist.","g_notice":"Õpilane valib kirja raami sõbrale ja asutusele (Lugupeetud…, Lugupidamisega), palub viisakalt ja annab edasi teise inimese sõnu.","g_use":"Õpilane lahendab keelekooliga telefonis proovieksami ja sünnipäeva kattumise, jätab Oskarile häälsõnumi ja kirjutab keelekoolile 100–130-sõnalise e-kirja."}},
  "a2b1-083": {"canDo":"Ma kirjutan 110–140-sõnalise arvamusteksti, kus on seisukoht, kaks põhjust, näide ja kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab arvamusteksti sõnu: seisukoht, esiteks, teiseks, kuigi, kokkuvõttes, veenma, lugejakiri, eelarve, väärtustama.","g_read":"Õpilane mõistab kahte lugejakirja ja raadiosaate „Linna hääl” arutelu ning leiab seisukoha, põhjused ja vastuargumendi.","g_notice":"Õpilane ehitab arvamusteksti (seisukoht, esiteks, teiseks, kokkuvõttes), lisab kuigi-lausega vastuargumendi ja täpsustab kes- / mis-lausega.","g_use":"Õpilane kaitseb arutelus kaardi seisukohta, räägib Maretile arutelu tulemusest ja kirjutab linnalehele 110–140-sõnalise lugejakirja."}},
  "a2b1-084": {"canDo":"Ma kirjeldan tabelit, sõiduplaani või küsitlust: sõnastan vähemalt viis fakti, kaks võrdlust ja ühe järelduse.","goals":{"g_vocab":"Õpilane kasutab andmete sõnu: küsitlus, vastaja, enamik, pooled, kolmandik, veerand, protsent, tulemus, ligi.","g_read":"Õpilane mõistab Tiina koosolekuettekannet küsitlusest, keelekooli uudiskirja arvudega ja elanike koosoleku protokolli.","g_notice":"Õpilane räägib arvudest õigete vormidega: enamik vastajatest soovib, pooled soovivad, üheksa vastajat, kõige rohkem.","g_use":"Õpilane lepib Tiinaga kokku teate sisu, kirjutab majale 50-sõnalise teate ja emale 100-sõnalise kirja proovieksami tulemustest."}},
  "a2b1-085": {"canDo":"Ma lahendan Harno B1 lugemise neli ülesannet ning kirjutan teate või ankeedi ja isikliku kirja või loo; tulemus vähemalt 70%.","goals":{"g_vocab":"Õpilane mõistab kuulutuste, kirjade, arvamuste ja andmete sõnavara ning kasutab kirja fraase ilma toeta.","g_read":"Õpilane lahendab Harno B1 lugemise neli ülesannet: olukord ↔ kuulutus, valikvastused, valikulüngad ja lauseosade pank.","g_notice":"Õpilane valib õige vormi ja sidesõna: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm, enamik + mitmus.","g_use":"Õpilane täidab ankeedi või kirjutab 50-sõnalise teate ning kirjutab 100-sõnalise isikliku kirja või loo."}},
  "a2b1-086": {"canDo":"Ma räägin tuttaval teemal 3–4 minutit märksõnaplaani järgi: algus, kaks-kolm mõtet näidetega ja kokkuvõte.","goals":{"g_vocab":"Õpilane kasutab monoloogi sõnu: eksamineerija, teema, märksõna, kõigepealt, esiteks, teisest küljest, kokkuvõtteks, tasakaal.","g_read":"Õpilane mõistab Sofia eksamimonoloogi, raadiosaadet B1 eksamist ja kooli uudiskirja ning leiab peamõtte, põhjused ja näited.","g_notice":"Õpilane ehitab monoloogi (algus, mõtted näidetega, teine külg, kokkuvõte) ja kasutab des-vormi: Tööle sõites kuulan raadiot.","g_use":"Õpilane peab Jaanina avatud uste päeval 3-minutilise kõne koolisööklast, vastab vanemate küsimustele ja kirjutab kodulehele teate."}},
  "a2b1-087": {"canDo":"Ma hoian 5-minutilist vestlust käigus: esitan vähemalt kolm täpsustavat või vastuküsimust, reageerin ja ütlen viisakalt, kas olen nõus.","goals":{"g_vocab":"Õpilane kasutab vestluse sõnu: täpsustama, vastuküsimus, reageerima, nõus, kokku leppima, arenguvestlus, julgema, ülesanne.","g_read":"Õpilane mõistab kohvipausi vestlust kontoris, Helgi kõnet pärast eksamit ja raadiointervjuud eksamineerijaga.","g_notice":"Õpilane täpsustab, küsib edasi ja vastu, reageerib ning moodustab kaudse küsimuse: Kas sa tead, millal arenguvestlused toimuvad?","g_use":"Õpilane peab Liisiga 5-minutilise arenguvestluse, räägib Markusele, kuidas läks, ja kirjutab Liisile kokkulepetest."}},
  "a2b1-088": {"canDo":"Ma lahendan teeninduses, transpordis, koolis või tööl tekkinud probleemi: selgitan, täpsustan, pakun kaks varianti ja jõuan lahenduseni ka siis, kui tingimus muutub.","goals":{"g_vocab":"Õpilane kasutab probleemi sõnu: tarnija, tellimus, kaup, hilinema, katki, hinnaalandus, hüvitama, tühistama, lahendus.","g_read":"Õpilane mõistab Jaani kirja tarnijale, tema telefonikõnet tarnijaga ja pere grupivestlust peost Viktori talus.","g_notice":"Õpilane kirjeldab probleemi umbisikulise minevikuga (kaup toodi hilja, ei toodud) ja tingiva minevikuga (Kui oleks helistatud, oleksin…).","g_use":"Õpilane räägib Helgile oma B1 aastast, lepib Jaaniga kokku peo kava, tellib telefonis bussi ja kirjutab õpetajale kursuse kohta."}},
  "a2b1-089": {"canDo": "Ma sooritan Harno B1 eksami vormis proovitöö kõigis neljas osaoskuses ajapiiri sees ja saan kokku vähemalt 70%.", "goals": {"g_read": "Õpilane lahendab ajapiiri sees Harno B1 kuulamise neli osa (30 punkti) ja lugemise neli osa (33 punkti).", "g_notice": "Õpilane valib valiklünktekstis ja keeleosas õige vormi: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm, rektsioon.", "g_use": "Õpilane kirjutab 50-sõnalise teate ja 100-sõnalise isikliku kirja ning lahendab rääkimise osad 1a, 1b ja 2."}},
  "a2b1-090": {"canDo": "Ma näitan B1 taset kõigis neljas osaoskuses: saan igas osas vähemalt 60% ja kokku vähemalt 70% ning tean oma järgmised eesmärgid.", "goals": {"g_read": "Õpilane saab teises proovieksamis kuulamises vähemalt 18/30 ja lugemises vähemalt 20/33 punkti (60%).", "g_notice": "Õpilane kasutab kirjutades ja rääkides piisavalt täpselt B1 grammatikat: umbisikuline tegumood, tingiv kõneviis, kaudne kõne, des-vorm.", "g_use": "Õpilane kirjutab teate ja loo, lahendab rääkimise osad nõutud ajas ning koostab tulemuste põhjal oma B1 → B2 eesmärkide kaardi."}},
};
